<script setup>
import { Head, router } from '@inertiajs/vue3'; import { ref } from 'vue'; import AppLayout from '../Layouts/AppLayout.vue';
const props=defineProps({records:Object,institutions:Array}); const form=ref({year:new Date().getFullYear(),probability:0,budgeted_amount:0,status:'Identificada'}); const editing=ref(null); function save(){router[editing.value?'put':'post'](editing.value?`/alertas-poa/${editing.value}`:'/alertas-poa',form.value,{onSuccess:()=>{editing.value=null;form.value={year:new Date().getFullYear(),probability:0,budgeted_amount:0,status:'Identificada'}}})} function edit(row){editing.value=row.id;form.value={institution_id:row.institution_id,project:row.project,year:row.year,partida:row.partida,quarter:row.quarter,probability:row.probability,budgeted_amount:row.budgeted_amount,executed_amount:row.executed_amount,estimated_date:row.estimated_date,status:row.status,notes:row.notes}} function execute(id){router.patch(`/alertas-poa/${id}/ejecutar`)} function remove(id){router.delete(`/alertas-poa/${id}`)}
</script>
<template><Head title="Alertas POA"/><AppLayout><main class="module-page"><h2>Alertas POA</h2><form class="module-form" @submit.prevent="save"><select v-model="form.institution_id"><option value="">Institución</option><option v-for="i in institutions" :value="i.id">{{i.name}}</option></select><input v-model="form.project" required placeholder="Proyecto"><input v-model="form.year" required type="number"><input v-model="form.partida" placeholder="Partida"><input v-model="form.quarter" type="number" min="1" max="4" placeholder="Trimestre"><input v-model="form.probability" required type="number" min="0" max="100" placeholder="Probabilidad"><input v-model="form.budgeted_amount" required type="number" min="0" placeholder="Presupuesto"><input v-model="form.estimated_date" type="date"><input v-model="form.status" required placeholder="Estado"><button class="module-primary">{{editing?'Actualizar':'Guardar'}} POA</button></form><p v-for="row in records.data" :key="row.id">{{row.year}} · {{row.partida}} · {{row.project}} · L {{row.executed_amount}} / {{row.budgeted_amount}} <button class="row-action" @click="edit(row)">Editar</button><button class="row-action" @click="execute(row.id)">Ejecutar 100%</button><button class="row-action delete" @click="remove(row.id)">Eliminar</button></p></main></AppLayout></template>
